<span class="line">        <span class="token keyword">const</span> rightPressed <span class="token operator">=</span> controller<span class="token punctuation">.</span>keys<span class="token punctuation">.</span>right<span class="token punctuation">.</span>pressed<span class="token punctuation">;</span></span>
