<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>spineBoy<span class="token punctuation">.</span><span class="token function">isSpawning</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
