<span class="line">	scene<span class="token punctuation">.</span>positionX <span class="token operator">-=</span> speed <span class="token operator">*</span> scene<span class="token punctuation">.</span>scale <span class="token operator">*</span> spineBoy<span class="token punctuation">.</span>direction<span class="token punctuation">;</span></span>
